<script>
  import { getCombobox } from './combobox.svelte.js'

  /**
   * @import { Snippet } from 'svelte'
   * @import { SelectedOption } from './select.svelte.js'
   */

  /**
   * @typedef {object} ChipsProps
   * @property {string} target Id of the options
   * @property {SelectedOption[]} selected Options shown as chips
   * @property {Snippet<[SelectedOption]>} [chip] Replaces a chip's label
   * @property {boolean | null} [disabled] Stops chips being removed
   * @property {string} [class]
   */

  /** @type {ChipsProps} */
  let { target, selected, chip, disabled = null, class: klass = '' } = $props()

  /**
   * removeChip
   * Tells the field a chip was removed.
   *
   * @param {string} value
   */
  function removeChip(value) {
    getCombobox(target)?.nodes.input.dispatchEvent(
      new CustomEvent('chipremove', { detail: { value } }),
    )
  }
</script>

{#if selected.length}
  <ul class="chips {klass}">
    {#each selected as option (option.value)}
      <li class="chip">
        {#if chip}{@render chip(option)}{:else}{option.label}{/if}
        <button
          class="chip-remove-button"
          aria-label="Remove {option.label}"
          {disabled}
          onclick={() => removeChip(option.value)}
          type="button"
        >
          <svg aria-hidden="true" fill="none" viewBox="0 0 24 24">
            <path
              d="M6 6L18 18M18 6L6 18"
              stroke="currentcolor"
              stroke-linecap="round"
              stroke-width="2"
            />
          </svg>
        </button>
      </li>
    {/each}
  </ul>
{/if}
